mapper.select:
SELECT USER_PWD
FROM USERS
WHERE USER_IDX = #{userIdx}

SELECT COUNT(*)
FROM USERS
WHERE USER_NICKNAME = #{userNickname}
  AND USER_IDX != #{userIdx}

mapper.update:
UPDATE USERS
SET USER_NICKNAME          = #{userNickname},
    USER_AGE               = #{userAge},
    IS_REGISTERED_BUSINESS = #{isRegisteredBusiness}
WHERE USER_IDX = #{userIdx}

UPDATE USERS
SET USER_PWD = #{newPwd}
WHERE USER_IDX = #{userIdx}

mapper.select:
SELECT COUNT(*)
FROM COMMUNITY_POST
WHERE USER_IDX = #{userIdx}

SELECT COUNT(*)
FROM POST_COMMENT
WHERE USER_IDX = #{userIdx}
